#include <WiFi.h>
#include <WebServer.h>

// ==========================================
// ВПИШИТЕ СЮДА ИМЯ И ПАРОЛЬ ВАШЕЙ WI-FI СЕТИ
// ==========================================
const char* ssid = "DIR-615T-0DBC";       // Например, "TP-LINK_1234"
const char* password = "23233010";      // Например, "12345678"

WebServer server(8080); // Создаем веб-сервер на 80 порту

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println("\nПодключение к Wi-Fi...");
  WiFi.begin(ssid, password);

  // Ждем подключения к Wi-Fi
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println("\nWi-Fi подключен!");
  Serial.print("IP-адрес платы: ");
  Serial.println(WiFi.localIP()); // Этот IP-адрес нужно будет ввести в браузере

  // Настраиваем страницу, которая откроется при заходе на IP-адрес
  server.on("/", []() {
    server.send(200, "text/html", "<h1>Hello from ESP32!</h1><p>Web Server is working.</p>");
  });

  server.begin();
  Serial.println("Веб-сервер запущен!");
}

void loop() {
  server.handleClient(); // Обрабатываем входящие запросы
}
